export default function Home() {
  const [screen, setScreen] = useState<"landing" | "app">("landing");
  const [role, setRole] = useState<Role>("Resident");
  const [view, setView] = useState("overview");
  const [deals, setDeals] = useState(dealsSeed);
  const [selectedDeal, setSelectedDeal] = useState<Deal | null>(null);
  const [createDrive, setCreateDrive] = useState(false);
  const [mobileOpen, setMobileOpen] = useState(false);
  const activeView = role === "Resident" ? (view === "overview" || view === "deals" || view === "bookings" || view === "society" ? view : "overview") : view === "overview" || view === "drives" || view === "calendar" || view === "members" || view === "opportunities" || view === "schedule" || view === "profile" || view === "analytics" || view === "approvals" || view === "support" ? view : "overview";
  const screenContent = useMemo(() => {
    if (role === "Resident") {
      if (activeView === "deals") return <DealsView deals={deals} onDeal={setSelectedDeal} />;
      if (activeView === "bookings") return <BookingsView />;
      return <ResidentOverview deals={deals} onDeal={setSelectedDeal} onView={setView} />;
    }
    if (role === "Secretary") return <SecretaryView onCreate={() => setCreateDrive(true)} />;
    if (role === "Vendor") return <VendorView />;
    return <AdminView />;
  }, [activeView, deals, role]);
  if (screen === "landing") return <Landing onEnter={() => { setScreen("app"); setRole("Resident"); setView("overview"); }} />;
  return <div className="min-h-screen bg-[#f7faf8] text-[#17221f]"><div className="flex min-h-screen"><Sidebar role={role} onRole={(r) => setRole(r)} view={activeView} onView={(v) => setView(v)} /><div className="min-w-0 flex-1"><Topbar role={role} onLanding={() => setScreen("landing")} onRole={(r) => { setRole(r); setView("overview"); }} onMobileMenu={() => setMobileOpen((x) => !x)} />{mobileOpen && <div className="fixed inset-x-0 top-[72px] z-40 border-b border-[#e7ece9] bg-white p-4 shadow-xl lg:hidden"><div className="mb-3 text-[9px] font-black uppercase tracking-[.18em] text-[#a3aea8]">Switch role</div><div className="grid grid-cols-2 gap-2">{(["Resident", "Secretary", "Vendor", "Admin"] as Role[]).map((r) => <button key={r} onClick={() => { setRole(r); setView("overview"); setMobileOpen(false); }} className={`rounded-xl border px-3 py-2 text-left text-[11px] font-bold ${role === r ? "border-[#f2c1a8] bg-[#fff5ef] text-[#d96e3d]" : "border-[#e8eeeb] text-[#718079]"}`}>{r}</button>)}</div></div>}<main className="mx-auto max-w-[1400px] p-5 pb-24 md:p-8 lg:pb-10"><Welcome role={role} />{screenContent}</main><MobileNav role={role} view={activeView} onView={setView} /></div></div>{selectedDeal && <DealDetail deal={selectedDeal} onClose={() => setSelectedDeal(null)} onJoined={(id, count) => { setDeals((items) => items.map((item) => item.id === id ? { ...item, booked: item.booked + count } : item)); }} />}{createDrive && <CreateDrive onClose={() => setCreateDrive(false)} />}</div>;
}

const deals = dealsSeed;

void deals;

export { formatInr, getTier };
